// GENERATED by scripts/sync-engine.mjs from src/engine/run-decision.ts. Do not edit here: edit the original and run "npm run sync-engine".
// Load everything about one field, run the engine, store the result. Used by the decision-engine Edge Function
// (called by the app and by the scheduler) and by the tests (on a real Postgres).

import { toNum, type Db } from './db.ts';
import { decideField, type DecideFieldInput, type FieldDecision, type ForecastInput } from './decide-field.ts';
import type { NutrientMeasurement } from './fertilization.ts';
import { dbRowToKcRow, KC_COLUMNS, type CropDbRow } from './kc-db.ts';
import type { WeatherRow } from './weather-summary.ts';

export class FieldNotFoundError extends Error {
  constructor(fieldId: string) {
    super(`field ${fieldId} not found`);
  }
}

export interface RunResult {
  decisionId: string;
  decision: FieldDecision;
}

const HOUR = 3_600_000;
const HEAT_CODE = 'fertilizer_hold_air_temp_max_c';

interface FieldRow { id: string; name: string; timezone: string | null; planting_date: string | null; area_m2: unknown; crop_id: string | null; soil_type_id: string | null }

export async function loadFieldInput(db: Db, fieldId: string, nowMs: number): Promise<DecideFieldInput> {
  const [field] = await db.select<FieldRow>('fields', { columns: 'id,name,timezone,planting_date,area_m2,crop_id,soil_type_id', eq: { id: fieldId }, limit: 1 });
  if (!field) throw new FieldNotFoundError(fieldId);

  // ---- crop, Kc row (Table 12), root depth + p (Table 22), stage lengths
  let crop: DecideFieldInput['crop'] = null;
  if (field.crop_id) {
    const [c] = await db.select<{ id: string; crop_name: string; coefficient_id: string | null; water_params_id: string | null }>('crops', {
      columns: 'id,crop_name,coefficient_id,water_params_id', eq: { id: field.crop_id }, limit: 1,
    });
    if (c) {
      let kcRow = null;
      let kcGroupRow = null;
      if (c.coefficient_id) {
        const [row] = await db.select<CropDbRow>('crop_coefficients', { columns: KC_COLUMNS, eq: { id: c.coefficient_id }, limit: 1 });
        if (row) {
          const numeric = (r: CropDbRow): CropDbRow => ({
            ...r,
            row_id: Number(r.row_id),
            kc_ini_min: toNum(r.kc_ini_min), kc_ini_max: toNum(r.kc_ini_max),
            kc_mid_min: toNum(r.kc_mid_min), kc_mid_max: toNum(r.kc_mid_max),
            kc_end_min: toNum(r.kc_end_min), kc_end_max: toNum(r.kc_end_max),
          });
          kcRow = dbRowToKcRow(numeric(row));
          const [group] = await db.select<CropDbRow>('crop_coefficients', { columns: KC_COLUMNS, eq: { section: row.section, row_type: 'group_row' }, limit: 1 });
          kcGroupRow = group ? dbRowToKcRow(numeric(group)) : null;
        }
      }
      let rootDepthMinM: number | null = null;
      let depletionFractionP: number | null = null;
      if (c.water_params_id) {
        const [w] = await db.select<{ root_depth_min_m: unknown; depletion_fraction_p: unknown }>('crop_water_params', {
          columns: 'root_depth_min_m,depletion_fraction_p', eq: { id: c.water_params_id }, limit: 1,
        });
        if (w) {
          rootDepthMinM = toNum(w.root_depth_min_m);
          depletionFractionP = toNum(w.depletion_fraction_p);
        }
      }
      const [g] = await db.select<{ initial_days: unknown; development_days: unknown; mid_days: unknown; late_days: unknown }>('crop_growth_stages', {
        columns: 'initial_days,development_days,mid_days,late_days', eq: { crop_id: c.id }, order: { column: 'created_at', ascending: false }, limit: 1,
      });
      const stages = g && [g.initial_days, g.development_days, g.mid_days, g.late_days].every((x) => toNum(x) !== null)
        ? { initialDays: toNum(g.initial_days) as number, developmentDays: toNum(g.development_days) as number, midDays: toNum(g.mid_days) as number, lateDays: toNum(g.late_days) as number }
        : null;
      crop = { name: c.crop_name, kcRow, kcGroupRow, stages, rootDepthMinM, depletionFractionP };
    }
  }

  // ---- soil
  let soil: DecideFieldInput['soil'] = null;
  let soilName: string | null = null;
  if (field.soil_type_id) {
    const [s] = await db.select<{ soil_name: string | null; field_capacity_pct: unknown; wilting_point_pct: unknown; source_id: string | null }>('soil_types', {
      columns: 'soil_name,field_capacity_pct,wilting_point_pct,source_id', eq: { id: field.soil_type_id }, limit: 1,
    });
    // rule: no scientific constant without a source. A soil row without source_id is treated as "soil data missing".
    if (s) soilName = s.soil_name;
    if (s) soil = s.source_id ? { fieldCapacityPct: toNum(s.field_capacity_pct), wiltingPointPct: toNum(s.wilting_point_pct) } : { fieldCapacityPct: null, wiltingPointPct: null };
  }

  // ---- sensor points and their latest readings
  const pointRows = await db.select<{ id: string; point_name: string }>('sensor_points', { columns: 'id,point_name', eq: { field_id: fieldId }, order: { column: 'point_name' } });
  const points = pointRows.map((p) => ({ id: p.id, name: p.point_name }));
  const readings = points.length
    ? (await db.select<{ sensor_point_id: string; measured_at: string; moisture: unknown; moisture_status: string | null }>('sensor_readings', {
        columns: 'sensor_point_id,measured_at,moisture,moisture_status',
        in: { sensor_point_id: points.map((p) => p.id) },
        gte: { measured_at: new Date(nowMs - 24 * HOUR).toISOString() },
        order: { column: 'measured_at', ascending: false },
        limit: 5000,
      })).map((r) => ({ sensorPointId: r.sensor_point_id, measuredAt: new Date(r.measured_at).toISOString(), moisture: toNum(r.moisture), moistureStatus: r.moisture_status }))
    : [];

  // ---- weather
  const weather: WeatherRow[] = (await db.select<Record<string, unknown>>('weather_observations', {
    columns: 'observed_at,air_temperature_c,precipitation_mm,rain_probability_pct,et0_mm',
    eq: { field_id: fieldId },
    gte: { observed_at: new Date(nowMs - 36 * HOUR).toISOString() },
    lte: { observed_at: new Date(nowMs + 60 * HOUR).toISOString() },
    order: { column: 'observed_at', ascending: true },
    limit: 500,
  })).map((w) => ({
    observed_at: new Date(w.observed_at as string).toISOString(),
    air_temperature_c: toNum(w.air_temperature_c),
    precipitation_mm: toNum(w.precipitation_mm),
    rain_probability_pct: toNum(w.rain_probability_pct),
    et0_mm: toNum(w.et0_mm),
  }));

  // ML is switched off for now: the engine decides from sensors, weather, soil and crop only, so every alert comes from the rules.
  const forecasts: ForecastInput[] = [];

  // ---- reference tables for fertilization and thresholds (empty until the owner adds sourced rows)
  type LimitRow = { nutrient: 'n' | 'p' | 'k'; unit: string; low_below: unknown; source_id: string; method_code?: string };
  let limitRows: LimitRow[] = [];
  if (field.crop_id) {
    try {
      limitRows = await db.select<LimitRow>('crop_nutrient_sufficiency', { columns: 'nutrient,unit,low_below,source_id,method_code', eq: { crop_id: field.crop_id } });
    } catch (e) {
      // the migration 20261024100000 (method_code) is not applied yet: read the limits without it; they then match no measurement
      console.error('crop_nutrient_sufficiency.method_code is not available yet', e);
      limitRows = await db.select<LimitRow>('crop_nutrient_sufficiency', { columns: 'nutrient,unit,low_below,source_id', eq: { crop_id: field.crop_id } });
    }
  }
  const nutrientReference = limitRows.flatMap((r) => (toNum(r.low_below) === null ? [] : [{ nutrient: r.nutrient, unit: r.unit, lowBelow: toNum(r.low_below) as number, sourceId: r.source_id, ...(r.method_code ? { methodCode: r.method_code } : {}) }]));

  // measured N, P, K of the field: the latest lab results and sensor values of each nutrient (a few of each kind, so a flood of sensor
  // values can never hide an older lab result). Never defaulted to 0. If the table is not there yet, fertilization stays "not measured".
  let nutrientMeasurements: NutrientMeasurement[] = [];
  let nutrientMethodLabels: Record<string, { en: string; ar: string }> = {};
  try {
    for (const nutrient of ['n', 'p', 'k'] as const) {
      for (const kind of ['lab', 'sensor'] as const) {
        const rows = await db.select<{ nutrient: 'n' | 'p' | 'k'; value: unknown; unit: string; method_code: string; source_kind: 'lab' | 'sensor'; measured_at: string }>('nutrient_measurements', {
          columns: 'nutrient,value,unit,method_code,source_kind,measured_at', eq: { field_id: field.id, nutrient, source_kind: kind }, order: { column: 'measured_at', ascending: false }, limit: 5,
        });
        for (const r of rows) {
          const v = toNum(r.value);
          if (v !== null) nutrientMeasurements.push({ nutrient: r.nutrient, value: v, unit: r.unit, methodCode: r.method_code, sourceKind: r.source_kind, measuredAt: r.measured_at });
        }
      }
    }
    const methods = await db.select<{ code: string; label_en: string; label_ar: string }>('nutrient_methods', { columns: 'code,label_en,label_ar' });
    nutrientMethodLabels = Object.fromEntries(methods.map((m) => [m.code, { en: m.label_en, ar: m.label_ar }]));
  } catch (e) {
    console.error('nutrient measurements are not available yet (migration 20261024100000?)', e);
    nutrientMeasurements = [];
  }
  const fertilizerRows = await db.select<{ id: string; name: string; n_pct: unknown; p2o5_pct: unknown; k2o_pct: unknown; source_id: string }>('fertilizers', { columns: 'id,name,n_pct,p2o5_pct,k2o_pct,source_id', order: { column: 'name', ascending: true } });
  const fertilizers = fertilizerRows.map((f) => ({ name: f.name, nPct: toNum(f.n_pct), p2o5Pct: toNum(f.p2o5_pct), k2oPct: toNum(f.k2o_pct), sourceId: f.source_id }));
  // dose ceilings of this crop and the sourced soil notes (all rows carry a source_id)
  const rates = field.crop_id
    ? (await db.select<{ nutrient: 'n' | 'p' | 'k'; min_kg_per_dunum: unknown; max_kg_per_dunum: unknown; basis_en: string; basis_ar: string; source_id: string }>('crop_nutrient_rates', { columns: 'nutrient,min_kg_per_dunum,max_kg_per_dunum,basis_en,basis_ar,source_id', eq: { crop_id: field.crop_id } }))
        .flatMap((r) => (toNum(r.max_kg_per_dunum) === null ? [] : [{ nutrient: r.nutrient, minKgPerDunum: toNum(r.min_kg_per_dunum), maxKgPerDunum: toNum(r.max_kg_per_dunum) as number, basisEn: r.basis_en, basisAr: r.basis_ar, sourceId: r.source_id }]))
    : [];
  const soilTypeNames = new Map((await db.select<{ id: string; soil_name: string | null }>('soil_types', { columns: 'id,soil_name' })).map((x) => [x.id, x.soil_name]));
  const fertilizerNames = new Map(fertilizerRows.map((f) => [f.id, f.name]));
  const soilNotes = (await db.select<{ fertilizer_id: string; soil_type_id: string | null; condition: string | null; rating: 'better' | 'caution'; note_en: string; note_ar: string; source_id: string }>('fertilizer_soil_notes', { columns: 'fertilizer_id,soil_type_id,condition,rating,note_en,note_ar,source_id' }))
    .flatMap((n) => {
      const fertilizerName = fertilizerNames.get(n.fertilizer_id);
      return fertilizerName ? [{ fertilizerName, soilName: n.soil_type_id ? soilTypeNames.get(n.soil_type_id) ?? null : null, condition: n.condition, rating: n.rating, noteEn: n.note_en, noteAr: n.note_ar, sourceId: n.source_id }] : [];
    });
  const thresholdRows = await db.select<{ crop_id: string | null; value: unknown; source_id: string }>('alert_thresholds', { columns: 'crop_id,value,source_id', eq: { code: HEAT_CODE } });
  const best = thresholdRows.find((t) => t.crop_id === field.crop_id && t.crop_id !== null) ?? thresholdRows.find((t) => t.crop_id === null);
  const heat = best && toNum(best.value) !== null ? { value: toNum(best.value) as number, sourceId: best.source_id } : null;

  return {
    field: { id: field.id, name: field.name, timezone: field.timezone, plantingDate: field.planting_date ? String(field.planting_date).slice(0, 10) : null, areaM2: toNum(field.area_m2) },
    soil,
    crop,
    points,
    readings,
    weather,
    forecasts,
    // measured N, P, K come from nutrient_measurements (lab results and NPK sensor values); with none, they are "not measured" (never 0)
    nutrients: { n: null, p: null, k: null },
    nutrientMeasurements,
    nutrientMethodLabels,
    nutrientReference,
    fertilizers,
    fertilizerHoldAirTempMaxC: heat,
    fertilizationContext: { rates, soilNotes, soilName },
    nowMs,
  };
}

/** stores the decision, its explanation, its alerts and the day's saving estimate */
export async function storeDecision(db: Db, fieldId: string, d: FieldDecision, pointIds: Set<string>): Promise<string> {
  const fresh = d.perPoint.map((p) => p.moisturePct).filter((m): m is number => m !== null);
  const meanMoisture = fresh.length ? fresh.reduce((s, v) => s + v, 0) / fresh.length : null;

  const irrigationJson = {
    status: d.irrigation.status,
    summary_en: d.irrigation.summaryEn,
    summary_ar: d.irrigation.summaryAr,
    points: d.perPoint.map((p) => ({
      point_id: p.pointId,
      name: p.pointName,
      moisture_pct: p.moisturePct,
      measured_at: p.measuredAt,
      status: p.result.status,
      reason: p.result.status === 'insufficient_data' ? p.result.reason : p.result.reason,
      missing: p.result.status === 'insufficient_data' ? p.result.fields : undefined,
      net_depth_mm: p.result.status === 'recommend_irrigation' ? p.result.netDepthMm : undefined,
      numbers: p.result.status === 'insufficient_data' ? undefined : p.result.numbers,
      text_en: p.text.en,
      text_ar: p.text.ar,
    })),
  };
  const fertJson = { status: d.fertilization.result.status, text_en: d.fertilization.text.en, text_ar: d.fertilization.text.ar, result: d.fertilization.result };

  const [row] = await db.insert<{ id: string }>('decisions', [{
    field_id: fieldId,
    generated_at: d.generatedAt,
    irrigation_decision: irrigationJson,
    fertilization_decision: fertJson,
    etc_mm: d.etcUsedMmDay,
    moisture_pct: meanMoisture,
    growth_stage: d.growthStage,
    engine_version: d.engineVersion,
    irrigation_status: d.irrigation.status,
    details: {
      local_day: d.localDay, day_of_season: d.dayOfSeason, kc: d.kc, et0_mm_day: d.et0MmDay, etc_range_mm_day: d.etcMmDay,
      upstream: d.upstream, saving: d.saving, explanation_ar: d.explanation.ar,
    },
  }], 'id');
  const decisionId = row.id;

  await db.insert('decision_explanations', [{ decision_id: decisionId, explanation_text: d.explanation.en, generated_at: d.generatedAt }]);

  if (d.alerts.length > 0) {
    await db.insert('alerts', d.alerts.map((a) => ({
      field_id: fieldId,
      decision_id: decisionId,
      sensor_point_id: a.pointId && pointIds.has(a.pointId) ? a.pointId : null,
      kind: a.kind,
      code: a.code,
      severity: a.severity,
      title_en: a.titleEn,
      title_ar: a.titleAr,
      message_en: a.messageEn,
      message_ar: a.messageAr,
      details: a.details,
    })));
  }

  if (d.saving && d.localDay) {
    await db.upsert('water_savings', {
      field_id: fieldId, decision_id: decisionId, local_day: d.localDay, saved_mm: d.saving.savedMm, saved_m3: d.saving.savedM3, basis: d.saving.basis,
    }, 'field_id,local_day');
  }
  return decisionId;
}

export async function runDecisionForField(db: Db, fieldId: string, nowMs: number): Promise<RunResult> {
  const input = await loadFieldInput(db, fieldId, nowMs);
  const decision = decideField(input);
  const decisionId = await storeDecision(db, fieldId, decision, new Set(input.points.map((p) => p.id)));
  return { decisionId, decision };
}
